import * as s from "../core/validation/index.js";
import type { EnumSchema } from "../core/validation/schema.js";

/**
 * Termination condition of the generation. `stop` means the API returned the full completions
 * generated by the model without running into any limits. `length` means the generation exceeded
 * `max_tokens` or the conversation exceeded the max context length.
 */
export const FinishReason1 = {
  Stop: "stop",
  Length: "length",
} as const;
export type FinishReason1 = (typeof FinishReason1)[keyof typeof FinishReason1] | (string & {});

export const finishReason1Schema: EnumSchema<FinishReason1> = s.enumOf<FinishReason1>(FinishReason1);
